int pipefd[2];

/* Standard pipe creation */
int status = pipe(pipefd);

/* Descriptor Mapping: */
// Read End:  pipefd[0] (Consumer)
// Write End: pipefd[1] (Producer)

/* pipe2() - Allows configuration flags */
#define PIPE_FLAGS (O_CLOEXEC | O_NONBLOCK)
int status2 = pipe2(pipefd, PIPE_FLAGS);

// Cleanup: close both ends when finished
if (status == 0) {
    close(pipefd[0]);
    close(pipefd[1]);
}
